tool_input.command:
$dirs = @("$env:USERPROFILE\.dsh\profiles\web","$env:USERPROFILE\.dsh")
foreach ($d in $dirs) {
  Get-ChildItem $d -Recurse -Include *.log,*.txt -ErrorAction SilentlyContinue |
    Where-Object { $_.LastWriteTime -gt (Get-Date).AddHours(-2) } |
    ForEach-Object {
      $hit = Select-String -Path $_.FullName -Pattern "orchestrator-gate loaded" -ErrorAction SilentlyContinue
      if ($hit) { Write-Output ("### " + $_.FullName); $hit | ForEach-Object { Write-Output $_.Line } }
    }
}
